/* ==========================================================================
   VETRI APEX ACADEMY - MAIN STYLESHEET
   A modern, professional, fully responsive design for Chennai's premier coaching institute.
   ========================================================================== */

/* --- CSS Variables & Design System --- */
:root {
  --primary: #0A1E3F;
  --primary-rgb: 10, 30, 63;
  --primary-light: #16325C;
  --primary-dark: #061226;
  --accent-gold: #F59E0B;
  --accent-gold-hover: #D97706;
  --accent-gold-light: #FEF3C7;
  --brand-blue: #2563EB;
  --brand-cyan: #06B6D4;
  --brand-teal: #0D9488;
  --brand-purple: #7C3AED;
  --brand-emerald: #059669;
  --whatsapp: #25D366;
  --whatsapp-dark: #128C7E;
  --whatsapp-light: #DCFCE7;

  --bg-body: #F8FAFC;
  --bg-surface: #FFFFFF;
  --bg-subtle: #F1F5F9;
  --bg-dark: #0B192C;

  --text-main: #0F172A;
  --text-muted: #475569;
  --text-light: #94A3B8;
  --text-white: #FFFFFF;

  --border-light: #E2E8F0;
  --border-focus: #3B82F6;
  --danger: #EF4444;
  --success: #10B981;

  --font-heading: 'Outfit', sans-serif;
  --font-body: 'Plus Jakarta Sans', sans-serif;

  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(10, 30, 63, 0.08), 0 2px 4px -2px rgba(10, 30, 63, 0.06);
  --shadow-lg: 0 10px 25px -3px rgba(10, 30, 63, 0.1), 0 4px 6px -4px rgba(10, 30, 63, 0.05);
  --shadow-xl: 0 20px 35px -5px rgba(10, 30, 63, 0.15), 0 8px 10px -6px rgba(10, 30, 63, 0.08);
  --shadow-glow: 0 0 25px rgba(245, 158, 11, 0.35);

  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 18px;
  --radius-full: 9999px;

  --transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
  --transition-slow: all 0.4s ease;
}

/* --- Base & Reset --- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-body);
  color: var(--text-main);
  background-color: var(--bg-body);
  line-height: 1.6;
  overflow-x: hidden;
  position: relative;
  -webkit-font-smoothing: antialiased;
}

a {
  color: inherit;
  text-decoration: none;
  transition: var(--transition);
}

ul {
  list-style: none;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

button, input, select, textarea {
  font-family: inherit;
  font-size: inherit;
  outline: none;
}

.container {
  width: 100%;
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 20px;
}

.text-center {
  text-align: center;
}

/* --- Typography Helpers --- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  color: var(--primary);
  font-weight: 700;
  line-height: 1.25;
}

.section {
  padding: 85px 0;
  position: relative;
}

.section-header {
  max-width: 760px;
  margin: 0 auto 50px auto;
}

.section-tag {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 16px;
  background-color: rgba(37, 99, 235, 0.1);
  color: var(--brand-blue);
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  border-radius: var(--radius-full);
  margin-bottom: 14px;
}

.section-tag.light {
  background-color: rgba(255, 255, 255, 0.15);
  color: var(--accent-gold);
}

.section-title {
  font-size: 2.35rem;
  margin-bottom: 16px;
  letter-spacing: -0.02em;
}

.section-subtitle {
  font-size: 1.1rem;
  color: var(--text-muted);
  line-height: 1.65;
}

.highlight-gradient {
  background: linear-gradient(135deg, #2563EB, #F59E0B);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 12px 24px;
  font-weight: 600;
  font-size: 0.95rem;
  border-radius: var(--radius-md);
  border: 1.5px solid transparent;
  cursor: pointer;
  transition: var(--transition);
  text-align: center;
  white-space: nowrap;
}

.btn-primary {
  background-color: var(--primary);
  color: var(--text-white);
  box-shadow: 0 4px 12px rgba(10, 30, 63, 0.25);
}

.btn-primary:hover {
  background-color: var(--primary-light);
  transform: translateY(-2px);
  box-shadow: 0 6px 18px rgba(10, 30, 63, 0.35);
}

.btn-secondary {
  background-color: var(--accent-gold);
  color: var(--primary-dark);
  font-weight: 700;
  box-shadow: 0 4px 14px rgba(245, 158, 11, 0.3);
}

.btn-secondary:hover {
  background-color: var(--accent-gold-hover);
  color: #fff;
  transform: translateY(-2px);
}

.btn-outline {
  background: transparent;
  color: var(--primary);
  border-color: var(--primary);
}

.btn-outline:hover {
  background-color: var(--primary);
  color: #fff;
}

.btn-whatsapp {
  background-color: var(--whatsapp);
  color: #fff;
  font-weight: 600;
}

.btn-whatsapp:hover {
  background-color: var(--whatsapp-dark);
  color: #fff;
  transform: translateY(-2px);
  box-shadow: 0 4px 14px rgba(37, 211, 102, 0.4);
}

.btn-sm {
  padding: 8px 16px;
  font-size: 0.85rem;
  border-radius: var(--radius-sm);
}

.btn-lg {
  padding: 15px 30px;
  font-size: 1.05rem;
  border-radius: var(--radius-md);
}

.full-width {
  width: 100%;
}

.mb-2 {
  margin-bottom: 8px;
}

.mt-1 {
  margin-top: 4px;
}

.mt-3 {
  margin-top: 14px;
}

/* --- Top Announcement Bar --- */
.top-bar {
  background-color: var(--primary-dark);
  color: #E2E8F0;
  font-size: 0.82rem;
  padding: 8px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.top-bar-content {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 10px;
}

.top-bar-left, .top-bar-right {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}

.badge-pill {
  background: var(--accent-gold);
  color: var(--primary-dark);
  padding: 2px 10px;
  border-radius: var(--radius-full);
  font-weight: 700;
  font-size: 0.72rem;
  text-transform: uppercase;
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.pulse {
  animation: pulseGlow 2s infinite;
}

@keyframes pulseGlow {
  0% { transform: scale(1); box-shadow: 0 0 0 0 rgba(245, 158, 11, 0.7); }
  70% { transform: scale(1.03); box-shadow: 0 0 0 8px rgba(245, 158, 11, 0); }
  100% { transform: scale(1); box-shadow: 0 0 0 0 rgba(245, 158, 11, 0); }
}

.top-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: #CBD5E1;
}

.top-link:hover {
  color: var(--accent-gold);
}

.campuses-tag {
  color: #94A3B8;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

/* --- Header / Navigation Bar --- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 1000;
  background-color: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-light);
  box-shadow: 0 2px 15px rgba(0, 0, 0, 0.04);
  transition: var(--transition);
}

.site-header.scrolled {
  padding: 4px 0;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08);
}

